// Rule and data files compiled into the binary (generated by cmake/embed.cmake).
#pragma once

#include <cstddef>

namespace aegis {

struct EmbeddedFile {
  const char* path;  // repository-relative, forward slashes
  const unsigned char* data;
  size_t size;
};

extern const EmbeddedFile kEmbeddedFiles[];
extern const size_t kEmbeddedFileCount;

}  // namespace aegis
